import dev.survivorcreator.hudscale.ScreenScale;import net.minecraft.client.Minecraft;
public class TestScale{public static class Screen{public int width,height;}public static void main(String[]a){var m=Minecraft.INSTANCE;for(int scale=1;scale<=6;scale++){m.window.scale=scale;var s=new Screen();ScreenScale.enter(s);if(s.width!=640||s.height!=360||m.window.scale!=scale)throw new AssertionError("dimensions/window "+scale);double logical=123;double physical=logical*3;double vanillaMouse=physical/scale;if(Math.abs(ScreenScale.input(vanillaMouse)-logical)>1e-6)throw new AssertionError("mouse "+scale);ScreenScale.exit(s);if(m.window.scale!=scale)throw new AssertionError("exit changed scale");}System.out.println("PASS GUI scales 1-6: virtual dimensions, mouse/drawing correspondence, no global mutation");}}
